def get_sitemap_tree(site_id, root_sitemap_id=None, include_urls=None, max_depth=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0022000" if __import__("os").path.isdir("./environment_mix/0022000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, re

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, site_id_val=None, root_id_val=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rlog_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "get_sitemap_tree",
            "status": status,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "site_id": site_id_val,
            "root_sitemap_id": root_id_val,
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # Basic rate limit (observable dynamics) using request_logs.json if present/used
    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        # 120 requests/minute across all endpoints
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-2000:]):
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", site_id, root_sitemap_id, {"error_code": rl["error"]["code"]})
        return rl

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^site_01H8[A-Z0-9]{15,}$", site_id):
        _log("error", site_id, root_sitemap_id, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid site_id format.")
    if root_sitemap_id is not None:
        if not isinstance(root_sitemap_id, str) or not re.match(r"^smap_01H8[A-Z0-9]{15,}$", root_sitemap_id):
            _log("error", site_id, root_sitemap_id, {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid root_sitemap_id format.")
    if include_urls is None:
        include_urls = False
    if not isinstance(include_urls, bool):
        _log("error", site_id, root_sitemap_id, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_urls must be a boolean.")
    if max_depth is None:
        max_depth = 1000000
    if not isinstance(max_depth, int) or max_depth < 0:
        _log("error", site_id, root_sitemap_id, {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "max_depth must be an integer >= 0.")

    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []
    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site:
        _log("error", site_id, root_sitemap_id, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Site not found.")
    if site.get("status") == "deleted":
        _log("error", site_id, root_sitemap_id, {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Site not found.")

    nodes = _load("sitemap_nodes.json")
    if not isinstance(nodes, list):
        nodes = []

    # Determine root_sitemap_id if not provided: most recently updated root for this site
    if root_sitemap_id is None:
        # Find candidate roots (nodes with depth==0) for this site
        roots = [n for n in nodes if n.get("site_id") == site_id and n.get("depth") == 0 and isinstance(n.get("root_sitemap_id"), str)]
        if roots:
            def _parse_dt(x):
                v = x.get("updated_at") or x.get("created_at")
                if not isinstance(v, str):
                    return datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
                try:
                    return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                except Exception:
                    return datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            roots.sort(key=_parse_dt, reverse=True)
            root_sitemap_id = roots[0].get("root_sitemap_id")
        else:
            # No tree persisted -> return empty snapshot (normal envelope)
            _log("ok", site_id, None, {"returned_nodes": 0})
            return {
                "site_id": site_id,
                "root_sitemap_id": None,
                "include_urls": include_urls,
                "max_depth": max_depth if max_depth != 1000000 else None,
                "nodes": [],
                "meta": {"total": 0}
            }

    # Filter nodes for this site+root
    scoped = [n for n in nodes if n.get("site_id") == site_id and n.get("root_sitemap_id") == root_sitemap_id]
    if not scoped:
        # root scope requested but not found => empty tree snapshot (reads return empty set)
        _log("ok", site_id, root_sitemap_id, {"returned_nodes": 0})
        return {
            "site_id": site_id,
            "root_sitemap_id": root_sitemap_id,
            "include_urls": include_urls,
            "max_depth": max_depth if max_depth != 1000000 else None,
            "nodes": [],
            "meta": {"total": 0}
        }

    # Enforce include_urls: filter out url nodes if false
    if not include_urls:
        scoped = [n for n in scoped if n.get("node_type") == "sitemap"]

    # Validate acyclic within same root_sitemap_id
    by_id = {n.get("id"): n for n in scoped if isinstance(n.get("id"), str)}
    # also need check parent refs within full scoped set (even if url nodes excluded, we check within returned set)
    visited = set()
    in_stack = set()
    def _dfs(nid):
        if nid in in_stack:
            return False
        if nid in visited:
            return True
        visited.add(nid)
        in_stack.add(nid)
        n = by_id.get(nid)
        pid = n.get("parent_node_id") if isinstance(n, dict) else None
        if pid is not None and isinstance(pid, str) and pid in by_id:
            if not _dfs(pid):
                return False
        in_stack.remove(nid)
        return True

    for nid in list(by_id.keys()):
        if not _dfs(nid):
            _log("error", site_id, root_sitemap_id, {"error_code": "CONFLICT"})
            return _err("CONFLICT", "Sitemap node hierarchy contains a cycle.", root_sitemap_id=root_sitemap_id)

    # Apply max_depth
    if max_depth != 1000000:
        scoped = [n for n in scoped if isinstance(n.get("depth"), int) and n.get("depth") <= max_depth]

    # Build tree adjacency for convenience
    children = {}
    for n in scoped:
        pid = n.get("parent_node_id")
        children.setdefault(pid, []).append(n)
    # Sort children deterministically by (node_type, label, id)
    for pid in list(children.keys()):
        children[pid].sort(key=lambda x: (str(x.get("node_type")), str(x.get("label")), str(x.get("id"))))

    # Identify root node(s): depth==0 preferred, else parent_node_id is null
    roots = [n for n in scoped if n.get("depth") == 0] or [n for n in scoped if n.get("parent_node_id") is None]
    roots.sort(key=lambda x: (str(x.get("label")), str(x.get("id"))))

    # Return flattened snapshot with derived children list (tree can be built client-side)
    out_nodes = []
    for n in scoped:
        nn = dict(n)
        nid = n.get("id")
        nn["children_ids"] = [c.get("id") for c in children.get(nid, []) if isinstance(c.get("id"), str)]
        out_nodes.append(nn)
    out_nodes.sort(key=lambda x: (int(x.get("depth") or 0), str(x.get("node_type")), str(x.get("label")), str(x.get("id"))))

    _log("ok", site_id, root_sitemap_id, {"returned_nodes": len(out_nodes)})
    return {
        "site_id": site_id,
        "root_sitemap_id": root_sitemap_id,
        "include_urls": include_urls,
        "max_depth": max_depth if max_depth != 1000000 else None,
        "roots": [r.get("id") for r in roots if isinstance(r.get("id"), str)],
        "nodes": out_nodes,
        "meta": {"total": len(out_nodes)}
    }

def get_sitemap_pages(site_id, sitemap_id=None, status=None, path_prefix=None, url_contains=None, discovered_after=None, discovered_before=None, lastmod_after=None, lastmod_before=None, changefreq=None, priority_min=None, priority_max=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0022000" if __import__("os").path.isdir("./environment_mix/0022000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, re, base64

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_val, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rlog_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "get_sitemap_pages",
            "status": status_val,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "site_id": site_id,
            "sitemap_id": sitemap_id,
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-2000:]):
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", {"error_code": rl["error"]["code"]})
        return rl

    # Validate inputs
    if not isinstance(site_id, str) or not re.match(r"^site_01H8[A-Z0-9]{15,}$", site_id):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid site_id format.")
    if sitemap_id is not None:
        if not isinstance(sitemap_id, str) or not re.match(r"^smap_01H8[A-Z0-9]{15,}$", sitemap_id):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid sitemap_id format.")
    if status is None:
        status = "active"
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "removed"):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid status; must be 'active' or 'removed'.")
    if path_prefix is not None and not isinstance(path_prefix, str):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "path_prefix must be a string.")
    if url_contains is not None and not isinstance(url_contains, str):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "url_contains must be a string.")
    valid_changefreq = ("always", "hourly", "daily", "weekly", "monthly", "yearly", "never")
    if changefreq is not None:
        if not isinstance(changefreq, str) or changefreq not in valid_changefreq:
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid changefreq value.")
    if priority_min is not None and not isinstance(priority_min, (int, float)):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "priority_min must be a number.")
    if priority_max is not None and not isinstance(priority_max, (int, float)):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "priority_max must be a number.")
    if priority_min is not None and (priority_min < 0.0 or priority_min > 1.0):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "priority_min must be within [0.0, 1.0].")
    if priority_max is not None and (priority_max < 0.0 or priority_max > 1.0):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "priority_max must be within [0.0, 1.0].")
    if priority_min is not None and priority_max is not None and priority_min > priority_max:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "priority_min cannot be greater than priority_max.")
    if sort is None:
        sort = "discovered_at"
    if not isinstance(sort, str) or sort not in ("discovered_at", "lastmod", "url", "created_at"):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort field.")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid order; must be 'asc' or 'desc'.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "BAD"
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return "BAD"

    for nm, val in (("discovered_after", discovered_after), ("discovered_before", discovered_before),
                    ("lastmod_after", lastmod_after), ("lastmod_before", lastmod_before)):
        if val is not None:
            dt = _parse_dt(val)
            if dt == "BAD":
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"{nm} must be an ISO 8601 date-time string.")

    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []
    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site or site.get("status") == "deleted":
        _log("error", {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Site not found.")

    pages = _load("sitemap_pages.json")
    if not isinstance(pages, list):
        pages = []

    # Filter
    filtered = [p for p in pages if p.get("site_id") == site_id]
    if status is not None:
        filtered = [p for p in filtered if p.get("status") == status]
    if sitemap_id is not None:
        filtered = [p for p in filtered if p.get("sitemap_id") == sitemap_id]
    if path_prefix is not None:
        filtered = [p for p in filtered if isinstance(p.get("path"), str) and p.get("path").startswith(path_prefix)]
    if url_contains is not None:
        filtered = [p for p in filtered if isinstance(p.get("url"), str) and url_contains in p.get("url")]
    if changefreq is not None:
        filtered = [p for p in filtered if p.get("changefreq") == changefreq]
    if priority_min is not None:
        filtered = [p for p in filtered if isinstance(p.get("priority"), (int, float)) and p.get("priority") >= float(priority_min)]
    if priority_max is not None:
        filtered = [p for p in filtered if isinstance(p.get("priority"), (int, float)) and p.get("priority") <= float(priority_max)]

    da = _parse_dt(discovered_after) if discovered_after is not None else None
    db = _parse_dt(discovered_before) if discovered_before is not None else None
    lma = _parse_dt(lastmod_after) if lastmod_after is not None else None
    lmb = _parse_dt(lastmod_before) if lastmod_before is not None else None

    if da is not None:
        def ok(p):
            dt = _parse_dt(p.get("discovered_at"))
            return isinstance(dt, datetime.datetime) and dt >= da
        filtered = [p for p in filtered if ok(p)]
    if db is not None:
        def ok(p):
            dt = _parse_dt(p.get("discovered_at"))
            return isinstance(dt, datetime.datetime) and dt <= db
        filtered = [p for p in filtered if ok(p)]
    if lma is not None:
        def ok(p):
            if p.get("lastmod") is None:
                return False
            dt = _parse_dt(p.get("lastmod"))
            return isinstance(dt, datetime.datetime) and dt >= lma
        filtered = [p for p in filtered if ok(p)]
    if lmb is not None:
        def ok(p):
            if p.get("lastmod") is None:
                return False
            dt = _parse_dt(p.get("lastmod"))
            return isinstance(dt, datetime.datetime) and dt <= lmb
        filtered = [p for p in filtered if ok(p)]

    # Deterministic ordering and stable cursor over (discovered_at,id) or (url_hash,id)
    sort_key = None
    cursor_mode = None
    if sort == "discovered_at":
        cursor_mode = "discovered_at"
        def sort_key(p):
            dt = _parse_dt(p.get("discovered_at"))
            if not isinstance(dt, datetime.datetime):
                dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            return (dt, str(p.get("id") or ""))
    elif sort == "url":
        cursor_mode = "url_hash"
        def sort_key(p):
            return (str(p.get("url_hash") or ""), str(p.get("id") or ""))
    elif sort == "lastmod":
        # If lastmod missing, push to end for desc, start for asc by using epoch
        cursor_mode = "lastmod"
        def sort_key(p):
            dt = _parse_dt(p.get("lastmod"))
            if not isinstance(dt, datetime.datetime):
                dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            return (dt, str(p.get("id") or ""))
    else:  # created_at
        cursor_mode = "created_at"
        def sort_key(p):
            dt = _parse_dt(p.get("created_at"))
            if not isinstance(dt, datetime.datetime):
                dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            return (dt, str(p.get("id") or ""))

    reverse = (order == "desc")
    filtered.sort(key=sort_key, reverse=reverse)

    def _encode_cursor(mode, a, b):
        payload = json.dumps({"v": 1, "mode": mode, "a": a, "b": b}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if not isinstance(c, str) or not c:
            return None
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return "BAD"
            return obj
        except Exception:
            return "BAD"

    # Apply cursor (exclusive)
    if cursor is not None:
        cobj = _decode_cursor(cursor)
        if cobj == "BAD":
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if cobj and cobj.get("mode") != cursor_mode:
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Cursor does not match current sort mode.")
        if cobj:
            a = cobj.get("a")
            b = cobj.get("b")
            def _after(item):
                k = sort_key(item)
                ka = k[0]
                kb = k[1]
                # convert cursor a to comparable
                if cursor_mode in ("discovered_at", "lastmod", "created_at"):
                    try:
                        ca = datetime.datetime.fromisoformat(str(a).replace("Z", "+00:00"))
                    except Exception:
                        return False
                    cb = str(b)
                    if not reverse:
                        return (ka, kb) > (ca, cb)
                    else:
                        return (ka, kb) < (ca, cb)
                else:
                    ca = str(a)
                    cb = str(b)
                    if not reverse:
                        return (ka, kb) > (ca, cb)
                    else:
                        return (ka, kb) < (ca, cb)
            filtered = [p for p in filtered if _after(p)]

    total = len(filtered)
    page = filtered[:limit]
    has_more = len(filtered) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        if cursor_mode in ("discovered_at", "lastmod", "created_at"):
            dt = _parse_dt(last.get(sort))
            if sort == "discovered_at":
                dt = _parse_dt(last.get("discovered_at"))
            elif sort == "created_at":
                dt = _parse_dt(last.get("created_at"))
            elif sort == "lastmod":
                dt = _parse_dt(last.get("lastmod"))
            if not isinstance(dt, datetime.datetime):
                dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            next_cursor = _encode_cursor(cursor_mode, dt.isoformat(), str(last.get("id") or ""))
        else:
            next_cursor = _encode_cursor(cursor_mode, str(last.get("url_hash") or ""), str(last.get("id") or ""))

    _log("ok", {"returned": len(page), "total": total, "has_more": has_more})
    return {
        "site_id": site_id,
        "pages": page,
        "meta": {
            "total": total,
            "limit": limit,
            "sort": sort,
            "order": order,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

