                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", {"error_code": rl["error"]["code"]})
        return rl

    if not isinstance(site_id, str) or not re.match(r"^site_01H8[A-Z0-9]{15,}$", site_id):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid site_id format.")
    if root_sitemap_id is not None:
        if not isinstance(root_sitemap_id, str) or not re.match(r"^smap_01H8[A-Z0-9]{15,}$", root_sitemap_id):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid root_sitemap_id format.")

    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []
    site = next((s for s in sites if s.get("id") == site_id), None)
    if not site or site.get("status") == "deleted":
        _log("error", {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Site not found.")

    sitemaps = _load("sitemaps.json")
    if not isinstance(sitemaps, list):
        sitemaps = []
    nodes = _load("sitemap_nodes.json")
    if not isinstance(nodes, list):
        nodes = []
    pages = _load("sitemap_pages.json")
    if not isinstance(pages, list):
        pages = []
    jobs = _load("parse_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    scoped_nodes = [n for n in nodes if n.get("site_id") == site_id]
    scoped_sitemaps = [s for s in sitemaps if s.get("site_id") == site_id]
    scoped_pages = [p for p in pages if p.get("site_id") == site_id and p.get("status") == "active"]

    if root_sitemap_id is not None:
        # root must exist for that site (either sitemap record, or nodes)
        root_exists = any(s.get("id") == root_sitemap_id and s.get("site_id") == site_id for s in scoped_sitemaps) or \
                      any(n.get("root_sitemap_id") == root_sitemap_id for n in scoped_nodes)
        if not root_exists:
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "root_sitemap_id not found for this site.")

        scoped_nodes = [n for n in scoped_nodes if n.get("root_sitemap_id") == root_sitemap_id]
        # sitemaps participating in this root: those referenced by nodes (sitemap_id) plus the root itself
        sitemap_ids = set()
        sitemap_ids.add(root_sitemap_id)
        for n in scoped_nodes:
            sid = n.get("sitemap_id")
            if isinstance(sid, str):
                sitemap_ids.add(sid)
        scoped_sitemaps = [s for s in scoped_sitemaps if s.get("id") in sitemap_ids]
        # pages: those belonging to sitemaps in this root set
        scoped_pages = [p for p in scoped_pages if p.get("sitemap_id") in sitemap_ids]

    # Aggregations
    total_sitemaps = len(scoped_sitemaps)
    total_pages = len(scoped_pages)
    max_depth = 0
    for n in scoped_nodes:
        d = n.get("depth")
        if isinstance(d, int) and d > max_depth:
            max_depth = d

    by_kind = {"sitemapindex": 0, "urlset": 0, "unknown": 0}
    for s in scoped_sitemaps:
        k = s.get("sitemap_kind")
        if k in by_kind:
            by_kind[k] += 1

    valid_changefreq = ("always", "hourly", "daily", "weekly", "monthly", "yearly", "never")
    by_changefreq = {k: 0 for k in valid_changefreq}
    by_changefreq["_null"] = 0
    for p in scoped_pages:
        cf = p.get("changefreq")
        if cf in by_changefreq:
            by_changefreq[cf] += 1
        else:
            by_changefreq["_null"] += 1

    # Failures: from parse_jobs and sitemaps failed
    failed_jobs = sum(1 for j in jobs if j.get("site_id") == site_id and j.get("status") == "failed")
    failed_sitemaps = sum(1 for s in scoped_sitemaps if s.get("status") == "failed")

    _log("ok", {"total_sitemaps": total_sitemaps, "total_pages": total_pages})
    return {
        "site_id": site_id,
        "root_sitemap_id": root_sitemap_id,
        "stats": {
            "total_sitemaps": total_sitemaps,
            "total_nodes": len(scoped_nodes),
            "total_pages": total_pages,
            "max_depth": max_depth,
            "count_by_sitemap_kind": by_kind,
            "count_by_changefreq": by_changefreq,
            "last_discovered_at": site.get("last_discovered_at"),
            "failure_counts": {
                "parse_jobs_failed": failed_jobs,
                "sitemaps_failed": failed_sitemaps
            }
        }
    }

def parse_sitemap_content(site_id, content, source_url=None, parent_sitemap_id=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0022000" if __import__("os").path.isdir("./environment_mix/0022000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, re, hashlib, urllib.parse, xml.etree.ElementTree as ET, random

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    def _log(status_code, code=None, message=None, **extra):
        # observable dynamics: always log request
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rlog_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "parse_sitemap_content",
            "timestamp": now,
            "status": int(status_code),
            "latency_ms": int((time.time() - t0) * 1000),
            "site_id": site_id,
            "source_url": source_url,
            "parent_sitemap_id": parent_sitemap_id,
        }
        if code is not None:
            row["error_code"] = code
        if message is not None:
            row["error_message"] = message
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # basic rate limit: 60 requests / 60s across service (store-driven)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        rnd = "".join(random.choice(alphabet) for _ in range(16))
        return f"{prefix}_01H8{rnd}"

    def _is_http_url(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _normalize_url(u):
        # minimal deterministic normalization for hashing/dedupe
        # keep scheme/host lowercased; strip fragment; keep path/query
        p = urllib.parse.urlsplit(u)
        scheme = (p.scheme or "").lower()
        netloc = (p.netloc or "").lower()
        path = p.path or "/"
        query = p.query or ""
        return urllib.parse.urlunsplit((scheme, netloc, path, query, ""))

    def _url_hash(u):
        return hashlib.sha256(u.encode("utf-8")).hexdigest()

    def _path_of(u):
        try:
            return urllib.parse.urlsplit(u).path or "/"
        except Exception:
            return None

    def _strip_ns(tag):
        if not isinstance(tag, str):
            return tag
        if "}" in tag:
            return tag.split("}", 1)[1]
        return tag

    def _safe_fromiso(dt_str):
        if dt_str is None:
            return None
        if not isinstance(dt_str, str) or not dt_str:
            return None
        try:
            return datetime.datetime.fromisoformat(dt_str.replace("Z", "+00:00"))
        except Exception:
            return None

    rl = _rate_limit_check()
    if rl:
        _log(429, rl["error"]["code"], rl["error"]["message"])
        return rl

    # ---- validate inputs (relax only to parameter schema; do not over-reject) ----
    if not isinstance(site_id, str) or not site_id:
        _log(400, "VALIDATION_ERROR", "site_id is required and must be a string")
        return _err("VALIDATION_ERROR", "site_id is required and must be a string", field="site_id")
    # keep the vendor pattern but do not hard-fail if it doesn't match: store contains only valid ids, caller may pass valid anyway
    if re.match(r"^site_01H8[A-Z0-9]{15,}$", site_id) is None:
        # accept but warn as validation error per spec? spec says refuses malformed IDs; however audit shows over-strictness elsewhere.
        # Here we enforce: malformed -> VALIDATION_ERROR.
        _log(400, "VALIDATION_ERROR", "site_id is malformed")
        return _err("VALIDATION_ERROR", "site_id is malformed", field="site_id")

    if not isinstance(content, str) or content == "":
        _log(400, "VALIDATION_ERROR", "content is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "content is required and must be a non-empty string", field="content")

    if source_url is not None:
        if not isinstance(source_url, str) or not source_url:
            _log(400, "VALIDATION_ERROR", "source_url must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "source_url must be a non-empty string when provided", field="source_url")
        if not _is_http_url(source_url):
            _log(400, "VALIDATION_ERROR", "source_url must be a valid http(s) URL")
            return _err("VALIDATION_ERROR", "source_url must be a valid http(s) URL", field="source_url")

    if parent_sitemap_id is not None:
        if not isinstance(parent_sitemap_id, str) or not parent_sitemap_id:
            _log(400, "VALIDATION_ERROR", "parent_sitemap_id must be a string when provided")
            return _err("VALIDATION_ERROR", "parent_sitemap_id must be a string when provided", field="parent_sitemap_id")
        if re.match(r"^smap_01H8[A-Z0-9]{15,}$", parent_sitemap_id) is None:
            _log(400, "VALIDATION_ERROR", "parent_sitemap_id is malformed")
            return _err("VALIDATION_ERROR", "parent_sitemap_id is malformed", field="parent_sitemap_id")

    sites = _load("sites.json")
    if not isinstance(sites, list):
        sites = []
    site_row = None
    for s in sites:
        if isinstance(s, dict) and s.get("id") == site_id:
            site_row = s
            break
    if site_row is None:
        _log(404, "NOT_FOUND", "site not found")
        return _err("NOT_FOUND", "site not found", site_id=site_id)
    if site_row.get("status") in ("disabled", "deleted"):
        # business rule: no new parse jobs for disabled/deleted
        _log(409, "INVALID_TRANSITION", "site is not active; cannot queue parse job")
        return _err("INVALID_TRANSITION", "site is not active; cannot queue parse job", site_id=site_id, status=site_row.get("status"))

    # parent sitemap reference validation
    sitemaps = _load("sitemaps.json")
    if not isinstance(sitemaps, list):
        sitemaps = []
    if parent_sitemap_id is not None:
        parent_row = None
        for sm in sitemaps:
            if isinstance(sm, dict) and sm.get("id") == parent_sitemap_id:
                parent_row = sm
                break
        if parent_row is None:
            _log(404, "NOT_FOUND", "parent sitemap not found")
            return _err("NOT_FOUND", "parent sitemap not found", parent_sitemap_id=parent_sitemap_id)
        if parent_row.get("site_id") != site_id:
            _log(409, "CONFLICT", "parent sitemap belongs to a different site")
            return _err("CONFLICT", "parent sitemap belongs to a different site", parent_sitemap_id=parent_sitemap_id, site_id=site_id)

    # ---- Create parse job (queued->running->succeeded/failed) ----
    parse_jobs = _load("parse_jobs.json")
    if not isinstance(parse_jobs, list):
        parse_jobs = []

    content_sha = hashlib.sha256(content.encode("utf-8")).hexdigest()
    job_id = _gen_id("pjob")
    job = {
        "id": job_id,
        "site_id": site_id,
        "input_type": "content",
        "input_url": source_url if source_url is not None else None,
        "input_content_sha256": content_sha,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "result_sitemap_id": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    parse_jobs.append(job)
    _save("parse_jobs.json", parse_jobs)

    # transition queued -> running
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("parse_jobs.json", parse_jobs)

    # ---- Parse content; accept non-XML by treating as unknown (do not hard fail) ----
    sitemap_kind = "unknown"
    discovered_urls = []
    discovered_child_sitemaps = []

    root_tag = None
    try:
        root = ET.fromstring(content.strip().encode("utf-8") if isinstance(content, str) else content)
        root_tag = _strip_ns(root.tag)
        if root_tag == "urlset":
            sitemap_kind = "urlset"
            for url_el in root.findall(".//"):
                if _strip_ns(url_el.tag) != "url":
                    continue
                loc = None
                lastmod = None
                changefreq = None
                priority = None
                for ch in list(url_el):
                    t = _strip_ns(ch.tag)
                    if t == "loc":
                        loc = (ch.text or "").strip()
                    elif t == "lastmod":
                        lastmod = (ch.text or "").strip() or None
                    elif t == "changefreq":
                        changefreq = (ch.text or "").strip() or None
                    elif t == "priority":
                        priority = (ch.text or "").strip() or None
                if loc:
                    discovered_urls.append({"loc": loc, "lastmod": lastmod, "changefreq": changefreq, "priority": priority})
        elif root_tag == "sitemapindex":
            sitemap_kind = "sitemapindex"
            for sm_el in root.findall(".//"):
                if _strip_ns(sm_el.tag) != "sitemap":
                    continue
                loc = None
                for ch in list(sm_el):
                    if _strip_ns(ch.tag) == "loc":
                        loc = (ch.text or "").strip()
                if loc:
                    discovered_child_sitemaps.append(loc)
        else:
            sitemap_kind = "unknown"
    except Exception:
        # Do not reject valid schema calls just because content isn't XML.
        sitemap_kind = "unknown"

    # ---- Upsert sitemap row ----
    # enforce constraints:
    # source_type=url implies source_url not null (we use content), source_type=content implies content_sha256 not null
    source_type = "content"

    # supersede previous row for same (site_id, source_url) when content_sha changes
    superseded_ids = []
    existing_same_source = None
    if source_url is not None:
        for sm in sitemaps:
            if isinstance(sm, dict) and sm.get("site_id") == site_id and sm.get("source_url") == source_url and sm.get("status") != "superseded":
                existing_same_source = sm
                break

    # if there is already a sitemap with same content_sha256 for site, prefer idempotency: return existing parsed row and still log+job succeed
    existing_same_content = None
    for sm in sitemaps:
        if isinstance(sm, dict) and sm.get("site_id") == site_id and sm.get("content_sha256") == content_sha:
            existing_same_content = sm
            break

    if existing_same_content is not None and existing_same_content.get("status") in ("parsed", "queued", "failed", "superseded"):
        sitemap_row = existing_same_content
        # if it was failed/queued, we will set it to parsed (legal transitions: failed->queued only, queued->parsed)
        # but we should not illegally jump failed->parsed.
        if sitemap_row.get("status") == "queued":
            sitemap_row["status"] = "parsed"
            sitemap_row["parsed_at"] = now
        elif sitemap_row.get("status") == "failed":
            # cannot go failed->parsed directly; keep as failed but still succeed job? No, success without effect.
            # We can create a new row with same sha? unique(site_id, content_sha256) forbids.
            # Therefore, we must re-queue then parse: failed->queued->parsed.
            sitemap_row["status"] = "queued"
            sitemap_row["updated_at"] = now
            sitemap_row["error_code"] = None
            sitemap_row["error_message"] = None
            sitemap_row["status"] = "parsed"
            sitemap_row["parsed_at"] = now
        # update derived fields
        sitemap_row["sitemap_kind"] = sitemap_kind
        sitemap_row["discovered_count"] = int(len(discovered_child_sitemaps) if sitemap_kind == "sitemapindex" else len(discovered_urls) if sitemap_kind == "urlset" else 0)
        sitemap_row["content_bytes"] = len(content.encode("utf-8"))
        sitemap_row["content_type"] = sitemap_row.get("content_type") or "application/xml"
        sitemap_row["updated_at"] = now
    else:
        sitemap_id = _gen_id("smap")
        sitemap_row = {
            "id": sitemap_id,
            "site_id": site_id,
            "parent_sitemap_id": parent_sitemap_id,
            "source_type": source_type,
            "source_url": source_url if source_url is not None else None,
            "content_sha256": content_sha,
            "content_bytes": len(content.encode("utf-8")),
            "content_type": "application/xml",
            "sitemap_kind": sitemap_kind,
            "status": "parsed",
            "parsed_at": now,
            "error_code": None,
            "error_message": None,
            "discovered_count": int(len(discovered_child_sitemaps) if sitemap_kind == "sitemapindex" else len(discovered_urls) if sitemap_kind == "urlset" else 0),
            "created_at": now,
            "updated_at": now,
        }
        # uniqueness constraints: (site_id, source_url) when source_url not null; (site_id, content_sha256) when not null
        # content sha uniqueness: ensured by existing_same_content check.
        if source_url is not None:
            for sm in sitemaps:
                if not isinstance(sm, dict):
                    continue
                if sm.get("site_id") == site_id and sm.get("source_url") == source_url and sm.get("id") != sitemap_row["id"]:
                    # if same content_sha, we'd have found existing_same_content via sha; so content differs
                    # supersede old row if transition allowed
                    old_status = sm.get("status")
                    if old_status in ("queued", "parsed", "failed"):
                        sm["status"] = "superseded"
                        sm["updated_at"] = now
                        superseded_ids.append(sm.get("id"))
                    # keep searching; there should be at most one, but tolerate dirty store
        sitemaps.append(sitemap_row)

    # persist sitemaps updates (including supersedes)
    _save("sitemaps.json", sitemaps)

    # update site last_discovered_at only when parsed
    site_row["last_discovered_at"] = now
    site_row["updated_at"] = now
    _save("sites.json", sites)

    # ---- Upsert pages only when sitemap_kind=urlset and sitemap is parsed ----
    pages_upserted = 0
    pages = _load("sitemap_pages.json")
    if not isinstance(pages, list):
        pages = []

    # verify referenced sitemap meets rule for inserting pages
    if sitemap_kind == "urlset" and sitemap_row.get("status") == "parsed":
        allowed_changefreq = {"always", "hourly", "daily", "weekly", "monthly", "yearly", "never"}
        for item in discovered_urls:
            loc = item.get("loc")
            if not _is_http_url(loc):
                # reject malformed URLs by skipping them (ingest still succeeds); count as error in job? don't fail whole job.
                continue
            norm = _normalize_url(loc)
            h = _url_hash(norm)
            path = _path_of(norm)
            lastmod_str = item.get("lastmod")
            lastmod_dt = _safe_fromiso(lastmod_str) if isinstance(lastmod_str, str) else None
            lastmod_out = lastmod_dt.isoformat() if lastmod_dt else None

            cf = item.get("changefreq")
            if cf is not None:
                if not isinstance(cf, str) or cf not in allowed_changefreq:
                    # invalid changefreq rejected: skip that row
                    continue

            pr = item.get("priority")
            pr_out = None
            if pr is not None:
                try:
                    prf = float(pr)
                except Exception:
                    continue
                if prf < 0.0 or prf > 1.0:
                    continue
                pr_out = prf

            existing = None
            for p in pages:
                if isinstance(p, dict) and p.get("site_id") == site_id and p.get("url_hash") == h:
                    existing = p
                    break
            if existing is None:
                pid = _gen_id("spage")
                row = {
                    "id": pid,
                    "site_id": site_id,
                    "sitemap_id": sitemap_row["id"],
                    "url": norm,
                    "url_hash": h,
                    "path": path,
                    "lastmod": lastmod_out,
                    "changefreq": cf,
                    "priority": pr_out,
                    "discovered_at": now,
                    "status": "active",
                    "created_at": now,
                    "updated_at": now,
                }
                pages.append(row)
                pages_upserted += 1
            else:
                # upsert: refresh fields and re-activate if removed
                existing["sitemap_id"] = sitemap_row["id"]
                existing["url"] = norm
                existing["path"] = path
                existing["lastmod"] = lastmod_out
                existing["changefreq"] = cf
                existing["priority"] = pr_out
                if existing.get("status") == "removed":
                    existing["status"] = "active"
                existing["updated_at"] = now
                pages_upserted += 1

        _save("sitemap_pages.json", pages)

    # ---- Refresh nodes for this root sitemap (single logical transaction best-effort) ----
    nodes = _load("sitemap_nodes.json")
    if not isinstance(nodes, list):
        nodes = []

    root_sitemap_id = sitemap_row["id"]
    # delete existing nodes for this root to rebuild (best-effort "transaction")
    new_nodes = [n for n in nodes if not (isinstance(n, dict) and n.get("site_id") == site_id and n.get("root_sitemap_id") == root_sitemap_id)]
    nodes = new_nodes

    def _add_node(node_type, parent_node_id, sitemap_id=None, page_id=None, label="", depth=0):
        nid = _gen_id("snode")
        row = {
            "id": nid,
            "site_id": site_id,
            "root_sitemap_id": root_sitemap_id,
            "parent_node_id": parent_node_id,
            "node_type": node_type,
            "sitemap_id": sitemap_id,
            "page_id": page_id,
            "label": label,
            "depth": int(depth),
            "child_count": 0,
            "created_at": now,
            "updated_at": now,
        }
        nodes.append(row)
        return row

    # root node (sitemap)
    root_label = (urllib.parse.urlsplit(source_url).path.rsplit("/", 1)[-1] if source_url else "sitemap")
    root_node = _add_node("sitemap", None, sitemap_id=root_sitemap_id, page_id=None, label=root_label or "sitemap", depth=0)

    if sitemap_kind == "sitemapindex":
        # create child sitemap nodes for discovered URLs (as labels only; no fetching/parsing here)
        for child_url in discovered_child_sitemaps:
            if not _is_http_url(child_url):
                continue
            label = urllib.parse.urlsplit(child_url).path.rsplit("/", 1)[-1] or child_url
            _add_node("sitemap", root_node["id"], sitemap_id=None, page_id=None, label=label, depth=1)
        root_node["child_count"] = sum(1 for n in nodes if isinstance(n, dict) and n.get("parent_node_id") == root_node["id"])
    elif sitemap_kind == "urlset":
        # link to page nodes for pages that belong to this sitemap_id (active only)
        for p in pages:
            if not isinstance(p, dict):
                continue
            if p.get("site_id") != site_id:
                continue
            if p.get("sitemap_id") != root_sitemap_id:
                continue
            if p.get("status") != "active":
                continue
            label = p.get("path") or p.get("url") or "url"
            _add_node("url", root_node["id"], sitemap_id=None, page_id=p.get("id"), label=label, depth=1)
        root_node["child_count"] = sum(1 for n in nodes if isinstance(n, dict) and n.get("parent_node_id") == root_node["id"])

    _save("sitemap_nodes.json", nodes)

    # ---- finalize job running->succeeded ----
    job["status"] = "succeeded"
    job["finished_at"] = now
    job["result_sitemap_id"] = sitemap_row["id"]
    job["updated_at"] = now
    _save("parse_jobs.json", parse_jobs)

    resp = {
        "data": {
            "parse_job": job,
            "sitemap": sitemap_row,
            "result": {
                "root_sitemap_id": root_sitemap_id,
                "sitemap_kind": sitemap_kind,
                "discovered_count": sitemap_row.get("discovered_count", 0),
                "superseded_sitemap_ids": superseded_ids,
                "discovered_child_sitemaps": discovered_child_sitemaps,
                "pages_upserted": pages_upserted,
            },
        }
    }
    _log(200, None, None, result_sitemap_id=sitemap_row["id"])
    return resp

def list_sites(status=None, host=None, canonical_url_contains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0022000" if __import__("os").path.isdir("./environment_mix/0022000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _encode_cursor(created_at, _id):
        payload = {"created_at": created_at, "id": _id}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj, dict) or "created_at" not in obj or "id" not in obj:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj["created_at"], str) or not isinstance(obj["id"], str):
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if _parse_dt(obj["created_at"]) is None:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return obj

    # Validate inputs
    allowed_status = {"active", "disabled", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")
    if host is not None and (not isinstance(host, str) or not host):
        return _err("VALIDATION_ERROR", "host must be a non-empty string")
    if canonical_url_contains is not None and (not isinstance(canonical_url_contains, str) or canonical_url_contains == ""):
        return _err("VALIDATION_ERROR", "canonical_url_contains must be a non-empty string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    cur_obj = _decode_cursor(cursor)
    if isinstance(cur_obj, dict) and "error" in cur_obj:
        return cur_obj

    req_started = datetime.datetime.now(datetime.timezone.utc)
    sites = _load("sites.json")

    # Filter
    def _match(row):
        if not isinstance(row, dict):
            return False
        if status is not None and row.get("status") != status:
            return False
        if host is not None and row.get("host") != host:
            return False
        if canonical_url_contains is not None:
            cu = row.get("canonical_url")
            if not isinstance(cu, str) or canonical_url_contains not in cu:
                return False
        return True

    rows = [r for r in sites if _match(r)]

    # Sort stable by created_at then id
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, r.get("id") or "")
    rows.sort(key=_sort_key)

    # Apply cursor (strictly after)
    if cur_obj is not None:
        cur_dt = _parse_dt(cur_obj["created_at"])
        cur_id = cur_obj["id"]

        def _after(r):
            rdt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            rid = r.get("id") or ""
            return (rdt, rid) > (cur_dt, cur_id)

        rows = [r for r in rows if _after(r)]

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("created_at"), last.get("id"))

    latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - req_started).total_seconds() * 1000)

    # No request-log collection declared in schema; nothing to persist for usage/audit beyond row timestamps.
    return {
        "data": page,
        "meta": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "order_by": ["created_at", "id"],
            "latency_ms": latency_ms,
        },
    }

def create_site(canonical_url, host=None, robots_txt_url=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0022000" if __import__("os").path.isdir("./environment_mix/0022000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, urllib.parse, re, random

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    def _ensure_list_or_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], obj
        if isinstance(obj, list):
            return obj, None
        return [], None

    def _write_logs(status_code, code=None, message=None, **extra):
        logs_obj = _load("request_logs.json")
        logs, wrapper = _ensure_list_or_rows(logs_obj)
        row = {
            "id": f"rlog_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "create_site",
            "timestamp": now,
            "status": int(status_code),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code is not None:
            row["error_code"] = code
        if message is not None:
            row["error_message"] = message
        if extra:
            row.update(extra)
        logs.append(row)
        if wrapper is not None:
            wrapper["rows"] = logs
            _save("request_logs.json", wrapper)
        else:
            _save("request_logs.json", logs)

    def _is_http_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _norm_host(h):
        if not isinstance(h, str):
            return None
        h = h.strip()
        if not h:
            return None
        # drop port if present
        if h.startswith("["):
            rb = h.find("]")
            if rb != -1:
                core = h[1:rb]
            else:
                core = h.strip("[]")
        else:
            core = h.split(":", 1)[0]
        core = core.strip().strip(".").lower()
        if not core:
            return None
        # allow punycode already; enforce lower(host) constraint
        return core

    def _host_from_url(u):
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return None
        netloc = p.netloc or ""
        if "@" in netloc:
            netloc = netloc.split("@", 1)[1]
        return _norm_host(netloc)

    def _norm_canonical(u):
        # Keep as a URL but normalize scheme/host casing and strip fragment
        p = urllib.parse.urlparse(u.strip())
        host_part = _host_from_url(u)
        if not host_part:
            return None
        scheme = p.scheme.lower()
        path = p.path or ""
        # keep trailing slash if provided; if empty path, normalize to "/"
        if path == "":
            path = "/"
        rebuilt = urllib.parse.urlunparse((scheme, host_part, path, "", "", ""))
        return rebuilt

    # ---- Validate inputs (relaxed host rules: accept host even if doesn't match canonical_url) ----
    if not isinstance(canonical_url, str) or not canonical_url.strip():
        _write_logs(400, "VALIDATION_ERROR", "canonical_url is required and must be a string", field="canonical_url")
        return _err("VALIDATION_ERROR", "canonical_url is required and must be a string", field="canonical_url")

    canonical_url_raw = canonical_url.strip()
    if not _is_http_url(canonical_url_raw):
        _write_logs(400, "VALIDATION_ERROR", "canonical_url must be an http(s) URL (constraint: canonical_url LIKE 'http%://%')", field="canonical_url")
        return _err("VALIDATION_ERROR", "canonical_url must be an http(s) URL (constraint: canonical_url LIKE 'http%://%')", field="canonical_url")

    if robots_txt_url is not None:
        if not isinstance(robots_txt_url, str) or not robots_txt_url.strip():
            _write_logs(400, "VALIDATION_ERROR", "robots_txt_url must be a non-empty string when provided", field="robots_txt_url")
            return _err("VALIDATION_ERROR", "robots_txt_url must be a non-empty string when provided", field="robots_txt_url")
        if not _is_http_url(robots_txt_url.strip()):
            _write_logs(400, "VALIDATION_ERROR", "robots_txt_url must be an http(s) URL", field="robots_txt_url")
            return _err("VALIDATION_ERROR", "robots_txt_url must be an http(s) URL", field="robots_txt_url")
        robots_txt_url = robots_txt_url.strip()

    if host is None:
        derived = _host_from_url(canonical_url_raw)
        if not derived:
            _write_logs(400, "VALIDATION_ERROR", "could not derive host from canonical_url", field="host")
            return _err("VALIDATION_ERROR", "could not derive host from canonical_url", field="host")
        host_norm = derived
    else:
        if not isinstance(host, str) or not host.strip():
            _write_logs(400, "VALIDATION_ERROR", "host must be a non-empty string when provided", field="host")
            return _err("VALIDATION_ERROR", "host must be a non-empty string when provided", field="host")
        host_norm = _norm_host(host)
        if not host_norm:
            _write_logs(400, "VALIDATION_ERROR", "host is invalid", field="host")
            return _err("VALIDATION_ERROR", "host is invalid", field="host")

    canonical_norm = _norm_canonical(canonical_url_raw)
    if not canonical_norm:
        _write_logs(400, "VALIDATION_ERROR", "canonical_url is invalid", field="canonical_url")
        return _err("VALIDATION_ERROR", "canonical_url is invalid", field="canonical_url")

    # ---- Load & enforce constraints ----
    sites_obj = _load("sites.json")
    sites, wrapper = _ensure_list_or_rows(sites_obj)

    # unique(host) constraint (treat any existing row as conflict, including deleted, per constraint)
    for r in sites:
        if isinstance(r, dict) and r.get("host") == host_norm:
            _write_logs(
                409,
                "CONFLICT",
                "a site with this host already exists (constraint: unique(host))",
                host=host_norm,
                site_id=r.get("id"),
            )
            return _err(
                "CONFLICT",
                "a site with this host already exists (constraint: unique(host))",
                host=host_norm,
                site_id=r.get("id"),
            )

    # ---- Create ----
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        # mimic existing style: site_01H8... (not strictly ULID, but stable prefix)
        return f"{prefix}_01H8{''.join(random.choice(alphabet) for _ in range(16))}"

    site_row = {
        "id": _new_id("site"),
        "canonical_url": canonical_norm,
        "host": host_norm,
        "robots_txt_url": robots_txt_url,
        "status": "active",
        "last_discovered_at": None,
        "created_at": now,
        "updated_at": now,
    }

    sites.append(site_row)
    if wrapper is not None:
        wrapper["rows"] = sites
        _save("sites.json", wrapper)
    else:
        _save("sites.json", sites)

    _write_logs(201)
    return {"data": site_row}

def update_site(site_id, canonical_url=None, robots_txt_url=None, status=None, **_extra):
    import json, os, datetime, re, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0022000" if __import__("os").path.isdir("./environment_mix/0022000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_http_url(u):
        if u is None:
            return True
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    # Validate site_id pattern
    if not isinstance(site_id, str) or not site_id:
        return _err("VALIDATION_ERROR", "site_id is required and must be a string")
    if re.match(r"^site_01H8[A-Z0-9]{15,}$", site_id) is None:
        return _err("VALIDATION_ERROR", "site_id is malformed")

    allowed_status = {"active", "disabled", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")
    if canonical_url is not None:
        if not isinstance(canonical_url, str) or not canonical_url:
            return _err("VALIDATION_ERROR", "canonical_url must be a non-empty string when provided")
        if not _is_http_url(canonical_url):
            return _err("VALIDATION_ERROR", "canonical_url must be a valid http(s) URL")
    if robots_txt_url is not None:
        if robots_txt_url != "" and not isinstance(robots_txt_url, str):
            return _err("VALIDATION_ERROR", "robots_txt_url must be a string when provided")
        if robots_txt_url == "":
            # treat empty string as null
            robots_txt_url = None
        if robots_txt_url is not None and not _is_http_url(robots_txt_url):
            return _err("VALIDATION_ERROR", "robots_txt_url must be a valid http(s) URL")

    if canonical_url is None and robots_txt_url is None and status is None:
        return _err("VALIDATION_ERROR", "no fields to update")

    sites = _load("sites.json")
    idx = None
    for i, r in enumerate(sites):
        if isinstance(r, dict) and r.get("id") == site_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "site not found", site_id=site_id)

    row = sites[idx]
    old_status = row.get("status")

    # Lifecycle transitions
    transitions = {
        "active": {"disabled", "deleted"},
        "disabled": {"active", "deleted"},
        "deleted": set(),
    }
    if status is not None:
        if old_status not in transitions:
            return _err("CONFLICT", "site has invalid current status", current_status=old_status)
        if status != old_status:
            if status not in transitions.get(old_status, set()):
                return _err("CONFLICT", "illegal status transition", from_status=old_status, to_status=status)

    # Apply updates
    changed = False
    if canonical_url is not None and canonical_url != row.get("canonical_url"):
        row["canonical_url"] = canonical_url
        changed = True
    if robots_txt_url is not None and robots_txt_url != row.get("robots_txt_url"):
        row["robots_txt_url"] = robots_txt_url
        changed = True
    if status is not None and status != old_status:
        row["status"] = status
        changed = True

    if not changed:
        # Idempotent: no-op update returns current row
        return {"data": row}

    row["updated_at"] = _now()
    sites[idx] = row
    _save("sites.json", sites)
    return {"data": row}

