    for i, r in enumerate(jobs_rows):
        if isinstance(r, dict) and r.get("id") == parse_job_id:
            idx = i
            job = r
            break

    if job is None:
        _log(404, "NOT_FOUND", "parse job not found")
        return _err("NOT_FOUND", "parse job not found", parse_job_id=parse_job_id)

    current = job.get("status")
    if current not in allowed_status:
        _log(409, "CONFLICT", "parse job has unknown status; cannot transition", current_status=current)
        return _err("CONFLICT", "parse job has unknown status; cannot transition", current_status=current)

    transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": {"queued"},
        "cancelled": {"queued"},
    }

    if status == current:
        # idempotent no-op update should still return the row
        _log(200)
        return {"data": job}

    if status not in transitions.get(current, set()):
        _log(
            409,
            "INVALID_TRANSITION",
            "illegal status transition (business rule: lifecycle transitions enforced)",
            from_status=current,
            to_status=status,
        )
        return _err(
            "INVALID_TRANSITION",
            "illegal status transition (business rule: lifecycle transitions enforced)",
            from_status=current,
            to_status=status,
        )

    # apply transition & timestamps
    job = dict(job)
    job["status"] = status
    job["updated_at"] = now

    if status == "running":
        if not job.get("started_at"):
            job["started_at"] = now
        job["finished_at"] = None
        job["error_code"] = None
        job["error_message"] = None
    elif status in ("succeeded", "failed", "cancelled"):
        if not job.get("started_at"):
            # allow completion timestamps even if started_at missing; fill to satisfy constraints
            job["started_at"] = job.get("started_at") or now
        job["finished_at"] = now
        if status == "succeeded":
            job["error_code"] = None
            job["error_message"] = None
        # for failed/cancelled, keep existing error fields if present

    jobs_rows[idx] = job
    if wrapper is not None:
        wrapper["rows"] = jobs_rows
        _save("parse_jobs.json", wrapper)
    else:
        _save("parse_jobs.json", jobs_rows)

    _log(200)
    return {"data": job}
